//! Implemented whole-fold metadata only. This enum issues no source, completion or execution receipt.
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum Policy{Tracked,TrackedTests,StateSchema,Lifecycle,Loot,InstanceList,Cache,OwnershipForms,Api,Fields,Appearance}
impl Policy{pub fn from_name(name:&str)->Option<Self>{match name{"tracked"=>Some(Self::Tracked),"tracked_tests"=>Some(Self::TrackedTests),"state_schema"=>Some(Self::StateSchema),"lifecycle"=>Some(Self::Lifecycle),"sys/loot"=>Some(Self::Loot),"instance_list"=>Some(Self::InstanceList),"cache"=>Some(Self::Cache),"sys/dx_ownership_forms"=>Some(Self::OwnershipForms),"api"=>Some(Self::Api),"sys/fields"=>Some(Self::Fields),"sys/appearance"=>Some(Self::Appearance),_=>None}}pub fn metadata(self)->&'static crate::lint::Meta{match self{Self::Tracked=>crate::tracked_policy::metadata(false),Self::TrackedTests=>crate::tracked_policy::metadata(true),Self::StateSchema=>&crate::state_schema_policy::META,Self::Lifecycle=>&crate::lifecycle_policy::META,Self::Loot=>crate::captured_sys_loot_pages::metadata(),Self::InstanceList=>&crate::instance_list_policy::META,Self::Cache=>&crate::cache_policy::META,Self::OwnershipForms=>crate::captured_sys_ownership_forms_pages::metadata(),Self::Api=>crate::captured_api_pages::metadata(),Self::Fields=>crate::captured_sys_fields_pages::metadata(),Self::Appearance=>crate::captured_sys_appearance_pages::metadata()}}pub fn name(self)->&'static str{self.metadata().name}pub fn tracked(self)->Option<bool>{match self{Self::Tracked=>Some(false),Self::TrackedTests=>Some(true),_=>None}}}

/// Borrowed output DATA. Only the concrete host that invokes the unique producer may lend it.
pub enum Data<'a>{Tracked(&'a crate::captured_tracked_pages::TrackedData),StateSchema(&'a crate::captured_state_schema_pages::StateSchemaData),Lifecycle(&'a crate::captured_lifecycle_pages::LifecycleData),Loot(&'a crate::captured_sys_loot_pages::LootData),InstanceList(&'a crate::captured_instance_list_pages::InstanceListData),Cache(&'a crate::captured_cache_bytes::CacheData),OwnershipForms(&'a crate::captured_sys_ownership_forms_pages::OwnershipFormsData),Api(&'a crate::captured_api_pages::ApiData),Fields(&'a crate::captured_sys_fields_pages::FieldData),Appearance(&'a crate::captured_sys_appearance_pages::AppearanceData)}
impl Data<'_>{pub fn sites(&self)->&[crate::lint::Site]{match self{Self::Tracked(d)=>d.sites(),Self::StateSchema(d)=>d.sites(),Self::Lifecycle(d)=>d.sites(),Self::Loot(d)=>d.sites(),Self::InstanceList(d)=>d.sites(),Self::Cache(d)=>d.sites(),Self::OwnershipForms(d)=>d.sites(),Self::Api(d)=>d.sites(),Self::Fields(d)=>d.sites(),Self::Appearance(d)=>d.sites()}}pub fn source_text(&self)->Option<&[String]>{match self{Self::Tracked(d)=>Some(d.source_text()),Self::Loot(d)=>Some(d.source_text()),Self::InstanceList(d)=>Some(d.source_text()),Self::OwnershipForms(d)=>Some(d.source_text()),Self::Api(d)=>Some(d.source_text()),Self::Fields(d)=>Some(d.source_text()),Self::Appearance(d)=>Some(d.source_text()),Self::StateSchema(_)|Self::Lifecycle(_)|Self::Cache(_)=>None}}pub fn allow_used(&self)->&[crate::lint::AllowUse]{match self{Self::Tracked(d)=>d.allow_used(),Self::Loot(d)=>d.allow_used(),Self::InstanceList(d)=>d.allow_used(),Self::Cache(d)=>d.allow_used(),Self::OwnershipForms(d)=>d.allow_used(),Self::Api(d)=>d.allow_used(),Self::Fields(d)=>d.allow_used(),Self::Appearance(d)=>d.allow_used(),Self::StateSchema(_)|Self::Lifecycle(_)=>&[]}}pub fn notes(&self)->&[String]{match self{Self::Tracked(d)=>d.notes(),Self::StateSchema(d)=>d.notes(),Self::Lifecycle(d)=>d.notes(),_=>&[]}}pub fn allow_source_digest(&self,rel:&str)->Option<&[u8;20]>{match self{Self::Tracked(d)=>d.allow_source_digest(rel),Self::Loot(d)=>d.allow_source_digest(rel),Self::InstanceList(d)=>d.allow_digests().get(rel),Self::Cache(d)=>d.allow_digests().get(rel),Self::OwnershipForms(d)=>d.allow_digests().get(rel),Self::Api(d)=>d.allow_source_digest(rel),Self::Fields(d)=>d.allow_source_digest(rel),Self::Appearance(d)=>d.allow_source_digest(rel),Self::StateSchema(_)|Self::Lifecycle(_)=>None}}}

impl Policy{pub fn message_only(self)->bool{matches!(self,Self::StateSchema|Self::Lifecycle|Self::Cache)}}

#[cfg(test)]mod tests{use super::*;#[test]fn exact_implemented_names_join_actual_metadata_without_claiming_complete_registry(){for policy in [Policy::Tracked,Policy::TrackedTests,Policy::StateSchema,Policy::Lifecycle,Policy::Loot,Policy::InstanceList,Policy::Cache,Policy::OwnershipForms,Policy::Api,Policy::Fields,Policy::Appearance]{assert_eq!(Policy::from_name(policy.name()),Some(policy));assert!(!matches!(policy.metadata().policy,crate::lint::Policy::Custom));if policy.message_only(){assert!(matches!(policy.metadata().policy,crate::lint::Policy::Hard));}assert!(Policy::from_name(&format!("{}_unported",policy.name())).is_none());}for name in ["scheduler","sem/reads","allow_annotations","init","decl"]{assert!(Policy::from_name(name).is_none());}}}

impl Policy{pub fn emits_notes(self)->bool{matches!(self,Self::Tracked|Self::TrackedTests|Self::StateSchema|Self::Lifecycle)}}
